import re

# More robust: find .unwrap() NOT inside mod tests {} or fn test functions
import os
for root, dirs, files in os.walk('src'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            lines = fh.readlines()

        # Simple heuristic: skip lines after '#[cfg(test)]' till end of file
        # or after '#[test]' in test functions
        in_test_module = False
        for i, line in enumerate(lines):
            if '#[cfg(test)]' in line:
                in_test_module = True
            if in_test_module:
                continue
            if '.unwrap()' in line and not line.strip().startswith('//'):
                print(f'{path}:{i+1}: {line.rstrip()}')
"

